contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to deposit and an amount to cash out.
    // We will deposit first (if deposit amount > MinDeposit) then attempt CashOut.
    function run(uint depositAmt, uint cashOutAmt) public payable {
        // ensure this contract has enough balance to forward deposit and potential cashOut (though cashOut sends from c back to this contract)
        require(address(this).balance >= depositAmt, "not enough balance to deposit");

        // read initial observable state
        uint beforeBalanceOfThis = c.balances(address(this));
        uint contractEthBefore = address(c).balance;

        // perform deposit call if desired; deposit only increases balance when msg.value > MinDeposit
        bool didDeposit = false;
        if (depositAmt > c.MinDeposit()) {
            // send depositAmt to c
            c.Deposit{value: depositAmt}();
            didDeposit = true;
        }

        uint afterDepositBalanceOfThis = c.balances(address(this));
        uint contractEthAfterDeposit = address(c).balance;

        // Now attempt CashOut; catch whether it reverts
        bool reverted;
        try c.CashOut(cashOutAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read final state
        uint finalBalanceOfThis = c.balances(address(this));
        uint contractEthFinal = address(c).balance;

        // If CashOut did not revert then:
        // - the contract's recorded balance for this address must have decreased by exactly cashOutAmt
        // - the ether held by c must have decreased by exactly cashOutAmt
        // Note: balances are uint, so express decrease as final = after - cashOutAmt when not reverted
        assert(
            reverted || (
                // only assert when cashOut succeeded: finalBalanceOfThis + cashOutAmt == afterDepositBalanceOfThis
                finalBalanceOfThis + cashOutAmt == afterDepositBalanceOfThis
                && contractEthFinal + cashOutAmt == contractEthAfterDeposit
            )
        );
    }

    receive() external payable {}
}

