    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount, "need funds to deposit");
        // observe initial recorded balance for this contract's address in c
        uint beforeBal = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        // perform Deposit with depositAmount (may be 0 or < MinDeposit, handled by c)
        c.Deposit{value: depositAmount}();

        // observe after deposit
        uint midBal = c.balances(address(this));
        uint midContractBalance = address(c).balance;

        // attempt CashOut of cashOutAmount, capture whether it reverted
        bool cashoutReverted;
        try c.CashOut(cashOutAmount) {
            cashoutReverted = false;
        } catch {
            cashoutReverted = true;
        }

        // observe final recorded balance and contract balance
        uint afterBal = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule expressed as a single assert:
        // 1) midBal equals beforeBal if depositAmount <= MinDeposit (Deposit ignores), otherwise midBal == beforeBal + depositAmount
        //    We cannot call MinDeposit directly (public) so we infer by comparing midContractBalance change vs depositAmount.
        // 2) CashOut, if succeeded (not reverted), reduces the recorded balance by exactly cashOutAmount and reduces contract's balance by cashOutAmount.
        // 3) CashOut never increases contract's balance.
        assert(
            // relation for deposit step: change in recorded balance equals change in contract balance (both either 0 or depositAmount)
            ( (midBal == beforeBal && midContractBalance == beforeContractBalance) || (midBal == beforeBal + depositAmount && midContractBalance == beforeContractBalance + depositAmount) )
            &&
            // cashout effect: if cashout reverted then state unchanged from mid to after for both recorded and contract balances
            ( cashoutReverted ? (afterBal == midBal && afterContractBalance == midContractBalance) : (
                // if not reverted, recorded balance decreased by cashOutAmount and contract balance decreased by cashOutAmount
                (afterBal + cashOutAmount == midBal) && (midContractBalance >= cashOutAmount) && (afterContractBalance + cashOutAmount == midContractBalance)
            ))
            &&
            // CashOut never increases contract balance
            (afterContractBalance <= midContractBalance)
        );
    }

    // receive to accept refunds if needed
    receive() external payable {}
}

